import java.util.*;

public class TopKBuilder {
    // Re-score only candidates: prevTop + heavyHitters. Never scan all videos.
    // Trade-off: may miss a dark-horse video; fixed by admitting sampled tail.
    public List<VideoScore> rebuildTopK(
            Set<String> candidates,
            BucketStore store,
            long windowStart, long windowEnd, int k) {
        PriorityQueue<VideoScore> heap =
            new PriorityQueue<>(Comparator.comparingLong(v -> v.count));
        for (String videoId : candidates) {
            long c = store.rangeSum(videoId, windowStart, windowEnd);
            if (c == 0) continue;
            if (heap.size() < k) heap.offer(new VideoScore(videoId, c));
            else if (c > heap.peek().count) {
                heap.poll();
                heap.offer(new VideoScore(videoId, c));
            }
        }
        List<VideoScore> out = new ArrayList<>(heap);
        out.sort((a, b) -> Long.compare(b.count, a.count));
        return out;
    }
    record VideoScore(String videoId, long count) {}
    interface BucketStore {
        long rangeSum(String videoId, long start, long end);
    }
}
